package com.productionhouse.crm.legal.contracts.service;
import com.productionhouse.crm.legal.contracts.dto.ContractRequest;import com.productionhouse.crm.legal.contracts.entity.ContractRecord;import com.productionhouse.crm.legal.contracts.repository.ContractRecordRepository;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class ContractRecordServiceTest{@Test void expiresActiveContractsAndOmitsFreeformNotesFromResponse(){var repo=mock(ContractRecordRepository.class);when(repo.save(any(ContractRecord.class))).thenAnswer(i->i.getArgument(0));var service=new ContractRecordService(repo,mock(MediaAssetRepository.class));var request=new ContractRequest("License",null,null,"LICENSE","Studio","Artist",null,"ACTIVE",java.time.LocalDate.now().minusYears(2),java.time.LocalDate.now().minusDays(1),null,"vault://contract","private legal note",true);var response=service.create(request);assertEquals("EXPIRED",response.status());assertFalse(java.util.Arrays.stream(response.getClass().getRecordComponents()).anyMatch(c->c.getName().equals("notes")));}}
